def test_factory_called_once():
    calls = []
    def factory(k):
        calls.append(k)
        return object()
    cache = {}
    a = get_or_create(cache, "x", factory)
    b = get_or_create(cache, "x", factory)
    assert a is b, "a cache hit should return the cached object"
    assert calls == ["x"], f"factory called {len(calls)} times"

